namespace Sace.Api.Tests;

public class Sprint6DischargeTests {
  [Fact] public async Task Peps_uses_oldest_entry_and_preserves_balance(){await using var f=await ImmexFixture.Create();var a=await f.Entry(new(2026,1,1),100);var b=await f.Entry(new(2026,2,1),100);var result=await f.Engine.ConfirmAsync(f.Exit(150),f.User.Id);var lines=result.Discharges.OrderBy(x=>x.Sequence).ToList();Assert.Equal([a.Id,b.Id],lines.Select(x=>x.InventoryEntryId));Assert.Equal([100m,50m],lines.Select(x=>x.QuantityDischarged));Assert.Equal(0,(await f.Db.ImmexInventoryEntries.FindAsync(a.Id))!.AvailableQuantity);Assert.Equal(50,(await f.Db.ImmexInventoryEntries.FindAsync(b.Id))!.AvailableQuantity);}
  [Fact] public async Task Peps_crosses_four_of_five_lots_in_deterministic_order(){await using var f=await ImmexFixture.Create();var entries=new List<ImmexInventoryEntry>();for(var i=0;i<5;i++)entries.Add(await f.Entry(new(2026,1,i+1),10));var result=await f.Engine.ConfirmAsync(f.Exit(35),f.User.Id);var lines=result.Discharges.OrderBy(x=>x.Sequence).ToList();Assert.Equal(entries.Take(4).Select(x=>x.Id),lines.Select(x=>x.InventoryEntryId));Assert.Equal([10m,10m,10m,5m],lines.Select(x=>x.QuantityDischarged));Assert.Equal(5,(await f.Db.ImmexInventoryEntries.FindAsync(entries[3].Id))!.AvailableQuantity);Assert.Equal(10,(await f.Db.ImmexInventoryEntries.FindAsync(entries[4].Id))!.AvailableQuantity);}
  [Fact] public async Task Unit_mismatch_requires_verified_conversion_without_mutating_balance(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,1),100,"KG");var preview=await f.Engine.PreviewAsync(f.Exit(50,"PZA"));Assert.Equal(ImmexDischargeOutcome.UNIT_CONVERSION_REQUIRED,preview.Outcome);await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Engine.ConfirmAsync(f.Exit(50,"PZA"),f.User.Id));Assert.Equal(100,(await f.Db.ImmexInventoryEntries.FindAsync(entry.Id))!.AvailableQuantity);Assert.Empty(await f.Db.ImmexInventoryDischarges.ToListAsync());}
  [Fact] public async Task Verified_decimal_unit_conversion_is_applied(){await using var f=await ImmexFixture.Create();await f.Entry(new(2026,1,1),10,"KG");f.Db.ImmexUnitConversions.Add(new(){MaterialId=f.Material.Id,FromUnit="G",ToUnit="KG",Factor=.001m,EffectiveFrom=new(2026,1,1),Source="Ficha técnica",IsVerified=true});await f.Db.SaveChangesAsync();var preview=await f.Engine.PreviewAsync(f.Exit(1000,"G"));Assert.Equal(1,preview.AllocatedQuantity);Assert.Equal(9,preview.Allocations.Single().EntryBalanceAfter);}
  [Fact] public async Task Over_discharge_never_creates_negative_balance(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,1),100);var result=await f.Engine.ConfirmAsync(f.Exit(150),f.User.Id);Assert.Equal(100,result.AllocatedQuantity);Assert.Equal(50,result.UnallocatedQuantity);Assert.Equal(0,(await f.Db.ImmexInventoryEntries.FindAsync(entry.Id))!.AvailableQuantity);Assert.Contains(await f.Db.ImmexInventoryIssues.ToListAsync(),x=>x.IssueCode=="UNALLOCATED_QUANTITY");}
  [Fact] public async Task Partial_and_full_discharge_update_operational_status(){await using var f=await ImmexFixture.Create();var partial=await f.Entry(new(2026,1,1),1000);await f.Engine.ConfirmAsync(f.Exit(700),f.User.Id);var p=await f.Db.ImmexInventoryEntries.FindAsync(partial.Id);Assert.Equal(300,p!.AvailableQuantity);Assert.Equal(ImmexInventoryEntryStatus.PARTIALLY_DISCHARGED,p.Status);var full=await f.Entry(new(2026,1,2),1000);await f.Engine.ConfirmAsync(f.Exit(1300),f.User.Id);var complete=await f.Db.ImmexInventoryEntries.FindAsync(full.Id);Assert.Equal(0,complete!.AvailableQuantity);Assert.Equal(ImmexInventoryEntryStatus.DISCHARGED,complete.Status);Assert.Equal(ImmexTemporalityOutcome.RESOLVED,complete.TemporalityOutcome);}
  [Fact] public async Task Reversal_restores_balance_and_preserves_original_line(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,1),100);var exit=await f.Engine.ConfirmAsync(f.Exit(100),f.User.Id);var line=Assert.Single(exit.Discharges);var reversal=await f.Engine.ReverseAsync(line.Id,"Salida cancelada con evidencia",f.User.Id);Assert.Equal(line.Id,reversal.OriginalDischargeId);Assert.Equal(100,(await f.Db.ImmexInventoryEntries.FindAsync(entry.Id))!.AvailableQuantity);Assert.Equal(1,await f.Db.ImmexInventoryDischarges.CountAsync());Assert.Equal(1,await f.Db.ImmexDischargeReversals.CountAsync());}
  [Fact] public async Task Fixed_asset_does_not_participate_in_material_peps(){await using var f=await ImmexFixture.Create();await f.Entry(new(2026,1,1),100,classification:ImmexInventoryClassification.FIXED_ASSET);var preview=await f.Engine.PreviewAsync(f.Exit(10));Assert.Equal(ImmexDischargeOutcome.INSUFFICIENT_INVENTORY,preview.Outcome);Assert.Empty(preview.Allocations);}
}

public class Sprint6TemporalityTests {
  [Fact] public async Task Eighteen_months_uses_calendar_arithmetic(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,15),100,classification:ImmexInventoryClassification.COMPONENT);await f.Rule("TEST-18",ImmexInventoryClassification.COMPONENT,ImmexDurationType.FIXED_PERIOD,18,ImmexDurationUnit.MONTH);var result=await f.Temporality.CalculateAsync(entry,new(2026,1,15));Assert.Equal(new DateTime(2027,7,15),result.DueDate);}
  [Fact] public async Task Two_years_uses_calendar_years(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,3,10),100,classification:ImmexInventoryClassification.CONTAINER);await f.Rule("TEST-2Y",ImmexInventoryClassification.CONTAINER,ImmexDurationType.FIXED_PERIOD,2,ImmexDurationUnit.YEAR);Assert.Equal(new DateTime(2028,3,10),(await f.Temporality.CalculateAsync(entry,new(2026,3,10))).DueDate);}
  [Fact] public async Task Program_validity_controls_fixed_asset_due_date(){await using var f=await ImmexFixture.Create();f.Program.ValidTo=new(2029,12,31);await f.Db.SaveChangesAsync();var entry=await f.Entry(new(2026,1,1),1,classification:ImmexInventoryClassification.FIXED_ASSET);await f.Rule("TEST-PROGRAM",ImmexInventoryClassification.FIXED_ASSET,ImmexDurationType.PROGRAM_VALIDITY,null,null);Assert.Equal(new DateTime(2029,12,31),(await f.Temporality.CalculateAsync(entry,new(2026,1,1))).DueDate);}
  [Fact] public async Task Ambiguous_classification_is_never_assigned_eighteen_months_by_default(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,1),10,classification:ImmexInventoryClassification.OTHER);var result=await f.Temporality.CalculateAsync(entry,new(2026,1,1));Assert.Equal(ImmexTemporalityOutcome.MANUAL_REVIEW,result.Outcome);Assert.Null(result.DueDate);}
  [Fact] public async Task Verified_specific_override_precedes_general_rule(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,1),10,classification:ImmexInventoryClassification.COMPONENT);await f.Rule("GENERAL",ImmexInventoryClassification.COMPONENT,ImmexDurationType.FIXED_PERIOD,18,ImmexDurationUnit.MONTH,10);await f.Rule("SPECIAL",ImmexInventoryClassification.COMPONENT,ImmexDurationType.FIXED_PERIOD,12,ImmexDurationUnit.MONTH,100,true);var result=await f.Temporality.CalculateAsync(entry,new(2026,1,1));Assert.Equal("SPECIAL",result.RuleCode);Assert.Equal(new DateTime(2027,1,1),result.DueDate);}
  [Theory][InlineData(60,ImmexTemporalityOutcome.DUE_SOON)][InlineData(15,ImmexTemporalityOutcome.DUE_CRITICAL)][InlineData(-1,ImmexTemporalityOutcome.PAST_DUE)] public async Task Threshold_outcomes_are_configurable(int days,ImmexTemporalityOutcome expected){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,1),10,classification:ImmexInventoryClassification.COMPONENT);await f.Rule("DAYS",ImmexInventoryClassification.COMPONENT,ImmexDurationType.FIXED_PERIOD,100,ImmexDurationUnit.DAY);var evaluation=entry.EntryDate.AddDays(100-days);Assert.Equal(expected,(await f.Temporality.CalculateAsync(entry,evaluation)).Outcome);}
  [Fact] public async Task Zero_balance_is_resolved_even_after_due_date(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,1),0,classification:ImmexInventoryClassification.COMPONENT);var result=await f.Temporality.CalculateAsync(entry,new(2030,1,1));Assert.Equal(ImmexTemporalityOutcome.RESOLVED,result.Outcome);}
}

public class Sprint6InventoryAndRiskTests {
  [Fact] public async Task Operation_import_is_idempotent_and_requires_explicit_temporary_evidence(){await using var f=await ImmexFixture.Create();var op=new TradeOperation{Folio="IMMEX-IMPORT",PedimentoNumber="26-1",PedimentoKey="IN",Period="2026-01",OperationDate=new(2026,1,2),TariffFraction="85011010",Quantity=100,Unit="PZA",GoodsDescription="Pieza",ImmexProgramId=f.Program.Id,IsTemporaryImport=true};f.Db.Add(op);await f.Db.SaveChangesAsync();var service=new ImmexInventoryImportService(f.Db,f.Temporality);Assert.Single(await service.ImportOperationAsync(op.Id,f.User.Id));Assert.Single(await service.ImportOperationAsync(op.Id,f.User.Id));Assert.Equal(1,await f.Db.ImmexInventoryEntries.CountAsync(x=>x.TradeOperationId==op.Id));}
  [Fact] public async Task Reconciliation_detects_quantity_inconsistency_without_autocorrecting(){await using var f=await ImmexFixture.Create();var entry=await f.Entry(new(2026,1,1),100);entry.AvailableQuantity=40;await f.Db.SaveChangesAsync();var issues=await f.Reconciliation.ReconcileAsync(f.Program.Id,f.User.Id);Assert.Contains(issues,x=>x.IssueCode=="QUANTITY_INCONSISTENCY");Assert.Equal(40,(await f.Db.ImmexInventoryEntries.FindAsync(entry.Id))!.AvailableQuantity);}
  [Fact] public async Task Reconciliation_detects_orphan_exit(){await using var f=await ImmexFixture.Create();f.Db.ImmexInventoryExits.Add(new(){ImmexProgramId=f.Program.Id,MaterialId=f.Material.Id,ExitType=ImmexExitType.RETURN,ExitDate=new(2026,2,1),Quantity=10,Unit="PZA",UnallocatedQuantity=10,DischargeOutcome=ImmexDischargeOutcome.INSUFFICIENT_INVENTORY});await f.Db.SaveChangesAsync();Assert.Contains(await f.Reconciliation.ReconcileAsync(f.Program.Id,f.User.Id),x=>x.IssueCode=="ORPHAN_EXIT");}
  [Fact] public async Task Immex_past_due_affects_risk_but_not_legal(){await using var f=await ImmexFixture.Create();var op=new TradeOperation{Folio="RISK-IMMEX",PedimentoNumber="26",Period="2026-01",OperationDate=new(2026,1,1),TariffFraction="1",ImmexProgramId=f.Program.Id,IsTemporaryImport=true};var profile=new RiskProfile{Code="TEST-V2",Version=2,Name="Test",Description="Operational",Status=RiskProfileStatus.ACTIVE,EffectiveFrom=new(2026,1,1),CategoryCapsJson="{\"IMMEX\":45}"};profile.Factors.Add(new(){Code="TEMPORALITY_PAST_DUE",Name="Past due",Category=RiskCategory.IMMEX,SourceType=RiskSourceType.IMMEX,SourceOutcome="TEMPORALITY_PAST_DUE",Weight=35,MaxPoints=35,Severity=RiskSeverity.CRITICAL,CorrelationMode=RiskCorrelationMode.MAX});f.Db.AddRange(op,profile);f.Db.ImmexInventoryEntries.Add(new(){ImmexProgramId=f.Program.Id,TradeOperation=op,MaterialId=f.Material.Id,PedimentoNumber="26",PedimentoKey="IN",EntryDate=new(2026,1,1),TariffFraction="1",Description="Part",OriginalQuantity=10,AvailableQuantity=10,TigieUnit="PZA",TemporalityOutcome=ImmexTemporalityOutcome.PAST_DUE,Status=ImmexInventoryEntryStatus.PAST_DUE});await f.Db.SaveChangesAsync();var result=await new OperationRiskScoringService(f.Db).CalculateAsync(op.Id,null,f.User.Id);Assert.Equal(35,result.NormalizedScore);Assert.Empty(await f.Db.Findings.ToListAsync());Assert.Empty(await f.Db.AuditResults.ToListAsync());}
  [Fact] public async Task Temporality_correlation_keeps_only_most_severe_factor_for_same_entry(){var definition1=new RiskFactorDefinition{Code="DUE",Category=RiskCategory.IMMEX,Weight=20,MaxPoints=20,CorrelationMode=RiskCorrelationMode.MAX};var definition2=new RiskFactorDefinition{Code="PAST",Category=RiskCategory.IMMEX,Weight=35,MaxPoints=35,CorrelationMode=RiskCorrelationMode.MAX};var entry=Guid.NewGuid();var rows=RiskScoringMath.Apply([new(definition1,"Entry",entry,"TEMPORALITY_CRITICAL","Critical","",$"IMMEX_TEMPORALITY:{entry}"),new(definition2,"Entry",entry,"TEMPORALITY_PAST_DUE","Past","",$"IMMEX_TEMPORALITY:{entry}")],new Dictionary<RiskCategory,decimal>());Assert.Single(rows);Assert.Equal(35,rows.Sum(x=>x.Points));}
}

public class Sprint6ApiSeedAndMigrationTests {
  [Theory][InlineData("GET","/api/immex/programs")][InlineData("POST","/api/immex/programs")][InlineData("GET","/api/immex/inventory")][InlineData("POST","/api/immex/discharges/preview")][InlineData("POST","/api/immex/temporalities/recalculate")][InlineData("GET","/api/immex/fixed-assets")][InlineData("GET","/api/immex/reports/balances")][InlineData("GET","/api/immex/dashboard")]
  public async Task Immex_endpoints_require_jwt(string method,string path){using var factory=new SaceFactory();var response=await factory.CreateClient().SendAsync(new HttpRequestMessage(new HttpMethod(method),path));Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);}
  [Fact] public async Task Seed_is_idempotent_traced_and_preserves_risk_v1(){using var factory=new SaceFactory();_ =factory.CreateClient();await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();Assert.Equal(8,await db.Annex24CoverageItems.CountAsync());Assert.True(await db.OfficialLegalSources.AnyAsync(x=>x.Code=="SAT-RGCE-ANEXO24-2026"&&x.Status==SourceVerificationStatus.VERIFIED));Assert.True(await db.ImmexTemporalityRules.Where(x=>x.Status==SourceVerificationStatus.VERIFIED).AllAsync(x=>x.OfficialSourceCitationId!=null));Assert.Equal(10,await db.RiskProfiles.Where(x=>x.Code=="RISK-OPS-V1").SelectMany(x=>x.Factors).CountAsync());Assert.Equal(8,await db.RiskProfiles.Where(x=>x.Code=="RISK-OPS-V2").SelectMany(x=>x.Factors).CountAsync(x=>x.SourceType==RiskSourceType.IMMEX));}
  [Fact] public async Task Incremental_and_down_migration_preserve_prior_data(){const string previous="20261026051506_BatchAuditAndRiskScoringV1";var dir=Path.Combine(Path.GetTempPath(),$"sace-s6-{Guid.NewGuid():N}");Directory.CreateDirectory(dir);var path=Path.Combine(dir,"test.db");try{var opId=Guid.NewGuid();var profileId=Guid.NewGuid();var scoreId=Guid.NewGuid();await using(var db=Context(path)){var migrator=db.Database.GetService<IMigrator>();await migrator.MigrateAsync(previous);var now="2026-10-26 00:00:00";await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO TradeOperations (Id,Folio,PedimentoNumber,OperationType,Period,OperationDate,PedimentoKey,TariffFraction,OriginCountry,DestinationCountry,CustomsRegime,IsImmex,PreferentialTreatment,Status,CreatedAt,UpdatedAt) VALUES ({opId},'KEEP-S6','26','Importacion','2026-10',{now},'IN','85011010','','','Temporal',1,0,'PendingAudit',{now},{now})");await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO RiskProfiles (Id,Code,Version,Name,Description,Status,LowMax,MediumMax,HighMax,CategoryCapsJson,CreatedAt,UpdatedAt) VALUES ({profileId},'KEEP',1,'Keep','Keep','ACTIVE',19,39,69,'{{}}',{now},{now})");await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO OperationRiskScores (Id,TradeOperationId,RiskProfileId,RiskProfileCode,RiskProfileVersion,Version,RawScore,NormalizedScore,RiskLevel,FactorCount,CriticalFactorCount,HighFactorCount,Explanation,CalculatedAt,SnapshotJson) VALUES ({scoreId},{opId},{profileId},'KEEP',1,1,0,0,'LOW',0,0,0,'Keep',{now},'{{}}')");await migrator.MigrateAsync();Assert.True(await Table(db,"ImmexInventoryEntries"));Assert.True(await Table(db,"ImmexInventoryDischarges"));await migrator.MigrateAsync(previous);}await using(var db=Context(path)){Assert.False(await Table(db,"ImmexInventoryEntries"));Assert.Equal(1,await Scalar(db,"SELECT COUNT(*) FROM TradeOperations"));Assert.Equal(1,await Scalar(db,"SELECT COUNT(*) FROM OperationRiskScores"));}}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(dir))Directory.Delete(dir,true);}}
  static SaceDbContext Context(string path)=>new(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite($"Data Source={path}").Options);static async Task<bool> Table(SaceDbContext db,string name)=>await Scalar(db,$"SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='{name}'")==1;static async Task<long> Scalar(SaceDbContext db,string sql){var c=(SqliteConnection)db.Database.GetDbConnection();if(c.State!=System.Data.ConnectionState.Open)await c.OpenAsync();await using var command=c.CreateCommand();command.CommandText=sql;return Convert.ToInt64(await command.ExecuteScalarAsync());}
}

sealed class ImmexFixture:IAsyncDisposable {
  readonly SqliteConnection connection;public SaceDbContext Db{get;}public User User{get;}public ImmexProgram Program{get;}public ImmexMaterial Material{get;}public ImmexTemporalityService Temporality{get;}public ImmexDischargeEngine Engine{get;}public ImmexInventoryReconciliationService Reconciliation{get;}
  ImmexFixture(SqliteConnection c,SaceDbContext db,User user,ImmexProgram program,ImmexMaterial material,ImmexTemporalityService temporality){connection=c;Db=db;User=user;Program=program;Material=material;Temporality=temporality;Engine=new(db);Reconciliation=new(db);}
  public static async Task<ImmexFixture>Create(){var c=new SqliteConnection("DataSource=:memory:");await c.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(c).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="IMMEX",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var program=new ImmexProgram{ProgramNumber=$"P-{Guid.NewGuid():N}",CompanyName="Test",Rfc="AAA010101AAA",Status=ImmexProgramStatus.ACTIVE};var material=new ImmexMaterial{ImmexProgram=program,MaterialCode="MAT-1",Description="Material",TariffFraction="85011010",TigieUnit="PZA"};db.AddRange(user,program,material);await db.SaveChangesAsync();var cfg=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"ImmexInventory:DueSoonDays","90"},{"ImmexInventory:CriticalDays","30"}}).Build();return new(c,db,user,program,material,new(db,cfg));}
  public async Task<ImmexInventoryEntry>Entry(DateTime date,decimal quantity,string unit="PZA",ImmexInventoryClassification classification=ImmexInventoryClassification.COMPONENT){var item=new ImmexInventoryEntry{ImmexProgramId=Program.Id,MaterialId=Material.Id,PedimentoNumber=$"PED-{date:MMdd}-{Guid.NewGuid():N}",PedimentoKey="IN",Sequence=1,EntryDate=date,TariffFraction=Material.TariffFraction,PartNumber=Material.MaterialCode,Description=Material.Description,OriginalQuantity=quantity,AvailableQuantity=quantity,TigieUnit=unit,InventoryClassification=classification,Status=quantity==0?ImmexInventoryEntryStatus.DISCHARGED:ImmexInventoryEntryStatus.OPEN};Db.Add(item);await Db.SaveChangesAsync();return item;}
  public ImmexExitRequest Exit(decimal quantity,string unit="PZA")=>new(Program.Id,null,ImmexExitType.RETURN,"OUT","RT",new(2026,6,1),null,Material.Id,quantity,unit,Material.TariffFraction,null,null);
  public async Task<ImmexTemporalityRule>Rule(string code,ImmexInventoryClassification classification,ImmexDurationType type,int? value,ImmexDurationUnit? unit,int priority=1,bool special=false){var source=new OfficialLegalSource{Code=$"SRC-{Guid.NewGuid():N}",Title="Official",SourceType=OfficialSourceType.OFFICIAL_COMPILATION,Authority="Authority",OfficialUrl="https://example.invalid",Status=SourceVerificationStatus.VERIFIED};var version=new OfficialLegalSourceVersion{OfficialLegalSource=source,VersionLabel="v1",PublicationDate=new(2025,1,1),EffectiveFrom=new(2025,1,1),OfficialUrl=source.OfficialUrl,VerificationStatus=SourceVerificationStatus.VERIFIED};var citation=new OfficialSourceCitation{OfficialLegalSourceVersion=version,CitationType=OfficialCitationType.ARTICLE,CitationLabel="Article"};var rule=new ImmexTemporalityRule{Code=code,Version=1,Name=code,InventoryClassification=classification,DurationType=type,DurationValue=value,DurationUnit=unit,EffectiveFrom=new(2025,1,1),Status=SourceVerificationStatus.VERIFIED,OfficialSourceCitation=citation,Priority=priority,IsOverride=special};Db.Add(rule);await Db.SaveChangesAsync();return rule;}
  public async ValueTask DisposeAsync(){await Db.DisposeAsync();await connection.DisposeAsync();}
}
